<script setup>
import { computed, ref, onMounted, onBeforeUnmount, nextTick, watch } from 'vue'
import { readDream, writeDream } from '../dream-account'
import { useRouter } from 'vue-router'
import { animate } from 'framer-motion'
import { cores, questions, scoreAnswers } from '../data/dream-cores'
const router=useRouter(), root=ref(null), stage=ref('cover'), step=ref(0), answers=ref([]), message=ref(''), saved=ref(false)
const question=computed(()=>questions[step.value]), ranking=computed(()=>scoreAnswers(answers.value)), main=computed(()=>cores[ranking.value[0].index]), secondary=computed(()=>cores[ranking.value[1].index])
const tint=computed(()=>stage.value==='result'?main.value.bg:cores[question.value.options[answers.value[step.value]]?.core??0].bg)
const disclaimer='本测试仅为潜意识氛围观察，娱乐向，不具备心理诊疗、解梦功能。'
let controls=[], media, timer
function notify(text){message.value=text;clearTimeout(timer);timer=setTimeout(()=>message.value='',4500)}
async function motion(){await nextTick();controls.forEach(c=>c.stop());controls=[];if(media?.matches||!root.value)return;root.value.querySelectorAll('[data-float]').forEach((el,i)=>controls.push(animate(el,{y:[0,-8,0]},{duration:10+i%3,repeat:Infinity,ease:'easeInOut',delay:i*.07})));const panel=root.value.querySelector('[data-panel]');if(panel)controls.push(animate(panel,{opacity:[.35,1],y:[8,0]},{duration:.45,ease:[.16,1,.3,1]}))}
watch([stage,step],motion)
onMounted(()=>{media=matchMedia('(prefers-reduced-motion: reduce)');media.addEventListener('change',motion);motion()})
onBeforeUnmount(()=>{controls.forEach(c=>c.stop());clearTimeout(timer);media?.removeEventListener('change',motion)})
function begin(){answers.value=[];step.value=0;saved.value=false;stage.value='quiz'}
function select(i){answers.value[step.value]=i}
function next(){if(answers.value[step.value]===undefined)return;if(step.value<11)step.value++;else{stage.value='result';nextTick(()=>root.value?.querySelector('h2')?.focus())}}
function radarPoint(i,ratio=1){const angle=(i*45-90)*Math.PI/180;return [160+Math.cos(angle)*100*ratio,150+Math.sin(angle)*100*ratio]}
const radar=computed(()=>cores.map((_,i)=>radarPoint(i,.12+ranking.value.find(x=>x.index===i).score/100*.88).join(',')).join(' '))
async function save(){
 if(saved.value)return router.push('/dream')
 const now=new Date(), date=now.toLocaleDateString('sv-SE');const night=new Date(now);night.setDate(night.getDate()-1)
 // Save the authored report to this account’s snapshot collection.
 const item={id:Date.now(),kind:'core-report',title:main.value.name+' × '+secondary.value.name+' · 梦核图鉴',date,nightDate:night.toLocaleDateString('sv-SE'),signal:main.value.slogan,feeling:main.value.feeling,motif:main.value.name,locked:false,coreReport:{primary:main.value.name,secondary:secondary.value.name,scores:ranking.value,answers:[...answers.value],inner:main.value.inner,gravity:main.value.gravity}}
 try{await writeDream('snapshots',[item,...readDream('snapshots',[])]);saved.value=true;notify('已保存到当前账号的意识碎片流')}
 catch(error){notify(error.message||'保存未完成，请保留结果后重试。')}
}
async function share(){
 try{const c=document.createElement('canvas');c.width=1080;c.height=1440;const x=c.getContext('2d');x.fillStyle=main.value.bg;x.fillRect(0,0,1080,1440);x.fillStyle='#fffdf8';x.save();x.translate(540,500);x.rotate(-.035);x.shadowColor='#998ab633';x.shadowBlur=30;x.fillRect(-390,-340,780,800);const image=new Image();image.src=main.value.art;await image.decode();x.shadowBlur=0;const scale=Math.max(700/image.width,560/image.height);x.save();x.beginPath();x.rect(-350,-300,700,560);x.clip();x.drawImage(image,-image.width*scale/2,-20-image.height*scale/2,image.width*scale,image.height*scale);x.restore();x.fillStyle='#625c75';x.textAlign='center';x.font='44px serif';x.fillText(main.value.name+' × '+secondary.value.name,0,345);x.restore();x.textAlign='center';x.fillStyle='#625c75';x.font='30px sans-serif';x.fillText('花屿星 · 梦核图鉴',540,110);x.font='40px serif';x.fillText(main.value.slogan,540,1090);x.font='23px sans-serif';x.fillText('一份关于梦境氛围的个人观察',540,1170);x.font='19px sans-serif';x.fillText('娱乐向 · 不具备心理诊疗、解梦功能',540,1330);c.toBlob(blob=>{if(!blob)return notify('海报未生成，请重试');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='花屿星-'+main.value.name+'-梦核图鉴.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('分享海报已生成，请查看下载')},'image/png')}
 catch{notify('海报素材加载失败，请稍后重试。')}
}
</script>
<template>
<main ref="root" class="core-atlas relative mx-auto max-w-6xl" :style="{'--core-tint':tint}">
 <header class="atlas-heading"><h1>梦核图鉴</h1><p>潜入你的潜意识，找到专属于你的梦境内核。</p></header>
 <section v-if="stage==='cover'" class="cover" data-panel>
  <div class="polaroid-gallery" aria-label="八种梦境内核画廊"><div v-for="(core,i) in cores" :key="core.name" class="photo-position" :class="'photo-'+i"><button data-float class="polaroid" :style="{'--rotation':(i%2?-1:1)*(4+i%3)+'deg'}" @click="notify(core.name+' · '+core.slogan)" :aria-label="core.name+'氛围预览'"><img :src="core.art" :alt="core.name+'氛围画面'" loading="lazy"><span>{{core.name}}</span></button></div></div>
  <div class="cover-copy"><span class="small-note">十二个片刻，留下一种底色</span><h2>找到你的梦境内核</h2><p>12 道梦境设问，看看你的潜意识<br>愿意栖居在哪一种世界。</p><button class="primary dive" @click="begin">开始潜入梦境测试 <span aria-hidden="true">↗</span></button><small>梦核 / 怪核 / 童话核 / 天使核<br>池核 / 水核 / 水晶核 / 雨核</small></div>
 </section>
 <section v-else-if="stage==='quiz'" class="quiz-panel" data-panel :key="step">
  <div class="quiz-meta"><button @click="stage='cover'">返回图鉴</button><span>意识漫游 {{String(step+1).padStart(2,'0')}} / 12</span></div>
  <div class="light-progress" role="progressbar" :aria-valuenow="step+1" :aria-valuemin="0" :aria-valuemax="12" aria-label="答题进度"><i :style="{transform:'scaleX('+((step+1)/12)+')'}"/></div>
  <h2>{{question.title}}</h2><p class="small-note">没有标准答案，选择最想停留的那一幕。</p>
  <div class="options"><button v-for="(option,i) in question.options" :key="i" :aria-pressed="answers[step]===i" :class="{selected:answers[step]===i}" @click="select(i)"><span>{{'ABCD'[i]}}</span>{{option.text}}<b v-if="answers[step]===i" aria-hidden="true">✓</b></button></div>
  <div class="quiz-footer"><button :disabled="step===0" @click="step--">上一题</button><span>{{answers.filter(x=>x!==undefined).length}} 个片刻已留下</span><button class="primary" :disabled="answers[step]===undefined" @click="next">{{step===11?'看见我的梦境内核':'沿着微光继续'}} →</button></div>
 </section>
 <section v-else class="report" data-panel>
  <div class="report-lead"><div><span class="small-note">你的本场氛围画像</span><h2 tabindex="-1">你的梦境内核是 <strong>{{main.name}}</strong></h2><p class="slogan">{{main.slogan}}</p><span class="core-pair">主核 {{main.name}} · 副核 {{secondary.name}}</span><p class="small-note" v-if="ranking[0].votes===ranking[1].votes">两种底色同样鲜明，主副顺序仅作展示。</p></div><svg class="radar" viewBox="0 0 320 300" role="img" :aria-label="'八维选择倾向：'+ranking.map(x=>cores[x.index].name+x.score+'%').join('，')"><defs><linearGradient id="atlas-fill"><stop stop-color="#a8c9d8" stop-opacity=".65"/><stop offset="1" stop-color="#c3b2da" stop-opacity=".5"/></linearGradient></defs><polygon v-for="r in [.25,.5,.75,1]" :key="r" :points="cores.map((_,i)=>radarPoint(i,r).join(',')).join(' ')" fill="none" stroke="#ddd9e7"/><line v-for="(_,i) in cores" :key="i" x1="160" y1="150" :x2="radarPoint(i)[0]" :y2="radarPoint(i)[1]" stroke="#e4dfeb"/><polygon :points="radar" fill="url(#atlas-fill)" stroke="#9c92ba" stroke-width="2" stroke-linejoin="round"/><text v-for="(core,i) in cores" :key="core.name" :x="radarPoint(i,1.25)[0]" :y="radarPoint(i,1.25)[1]+4" text-anchor="middle" fill="#746c88" font-size="12">{{core.name}}</text></svg></div>
  <div class="portrait-grid"><article class="paper"><h3>内在梦境</h3><p>{{main.inner}}</p></article><article class="paper"><h3>梦境引力</h3><p>{{main.gravity}}</p><button @click="router.push('/capture')">去体感快照留下此刻的感受 ↗</button></article></div>
  <section class="supplies"><h3>给这场梦，一点美学补给</h3><div class="supply-grid"><article class="paper"><span>梦境歌单</span><h4>{{main.music}}</h4><p>适合低声播放，留出自己的呼吸。</p></article><article class="paper"><span>梦境影像</span><h4>{{main.film}}</h4><p>只借一段画面，不急着寻找答案。</p></article><article class="paper"><span>梦境氛围参考</span><h4>{{main.objects}}</h4><p>用手边的小物，留住一点梦的质地。</p></article></div></section>
  <p class="small-note">八维图表示本场选项偏好，不代表心理量表分数。图鉴画面为项目内置氛围素材。</p>
  <div class="report-actions"><button class="primary" @click="save">{{saved?'去意识碎片流查看':'保存为本场意识快照'}}</button><button @click="share">生成分享海报</button><button @click="stage='cover'">重新潜入梦境</button></div>
 </section>
 <p class="disclaimer">{{disclaimer}}</p><p v-if="message" role="status" class="atlas-toast">{{message}}</p>
</main>
</template>
<style scoped>
