on:relative;margin-top:10px;isolation:isolate}.dive:before{content:'';position:absolute;inset:-6px;border:1px solid #d7cbe7;border-radius:19px;opacity:0;transition:transform 1s cubic-bezier(.16,1,.3,1),opacity 1s cubic-bezier(.16,1,.3,1)}.dive:hover:before{opacity:.6;transform:scale(1.07)}.quiz-panel{max-width:760px;margin:auto;padding:35px 35px 45px;min-height:570px}.quiz-meta,.quiz-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:12px;color:#90849f}.quiz-meta button{border:0;padding-left:0;background:transparent}.light-progress{height:4px;background:#e5dfec;border-radius:8px;margin:24px 0 45px;overflow:hidden}.light-progress i{display:block;width:100%;height:100%;transform-origin:left;background:linear-gradient(90deg,#b5ccd9,#c2b2d7,#f6f0ff);box-shadow:0 0 12px #bba4da;transition:transform .8s cubic-bezier(.16,1,.3,1)}.quiz-panel h2{font-family:serif;font-size:25px;font-weight:500;line-height:1.65}.options{display:flex;flex-direction:column;gap:13px;margin:28px 0 35px}.options button{text-align:left;display:flex;gap:17px;align-items:center;padding:19px 22px;background:#fffdf9b8;backdrop-filter:blur(8px);font-size:14px}.options button>span{font-family:serif;color:#a296b3}.options button>b{margin-left:auto;font-weight:400}.options .selected{border-color:#aa96c6;background:#efe9f8}.report{padding:25px 32px}.report-lead{display:grid;grid-template-columns:1fr 320px;align-items:center;gap:25px}.report h2{font-family:serif;font-size:27px;font-weight:400;line-height:1.8}.report h2 strong{display:block;color:#8a76a6;font-size:40px;font-weight:500}.slogan{font-family:serif;font-size:18px}.core-pair{display:inline-block;margin:12px 0;font-size:12px;border:1px solid #dbd2e7;border-radius:10px;padding:7px 12px}.radar{width:100%;max-width:320px}.portrait-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:20px 0 32px}.paper{border:1px solid #e4deec;border-radius:22px;padding:24px;background:#fffdf9b5}.paper h3,.supplies>h3{font-family:serif;font-weight:500;font-size:18px;margin:0 0 14px}.paper p{font-size:14px;line-height:1.9;color:#8a8197}.paper button{font-size:12px;padding:8px 11px}.supply-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.supply-grid article>span{font-size:12px;color:#9a8bab}.supply-grid h4{font-family:serif;font-size:16px;font-weight:400;line-height:1.8}.supply-grid p{font-size:12px}.report-actions{display:flex;flex-wrap:wrap;gap:12px;margin:24px 0}.disclaimer{text-align:center;font-size:11px;color:#968b9f;line-height:1.8;padding:22px 15px 0}.atlas-toast{position:fixed;bottom:35px;left:50%;transform:translateX(-50%);max-width:90vw;width:max-content;box-sizing:border-box;padding:14px 22px;border:1px solid #e0d7eb;border-radius:16px;background:#fffdf9;box-shadow:0 8px 30px #93819b22;z-index:100;font-size:13px}@media(hover:hover){.paper:hover,.polaroid:hover{transform:translateY(-4px);box-shadow:0 10px 30px #b4a1cc22}.options button:hover{transform:translateY(-2px)}}@media(max-width:1050px){.photo-position{width:125px}.polaroid img{height:110px}.cover-copy{padding-top:195px;width:62%}.cover-copy h2{font-size:26px}}@media(max-width:700px){.cover{min-height:770px}.photo-position{width:100px}.polaroid img{height:88px}.photo-0{left:5%;top:20px}.photo-1{left:37%;top:0}.photo-2{right:4%;top:35px}.photo-3{right:5%;top:185px}.photo-4{left:4%;top:175px}.photo-5{left:4%;top:560px}.photo-6{right:36%;top:610px}.photo-7{right:4%;top:550px}.cover-copy{padding-top:335px;width:92%}.cover-copy h2{font-size:26px}.quiz-panel,.report{padding:22px 16px}.quiz-panel h2{font-size:22px}.quiz-footer{flex-wrap:wrap}.quiz-footer>span{display:none}.quiz-footer button{font-size:12px}.report-lead{grid-template-columns:1fr;gap:0}.radar{margin:auto}.portrait-grid,.supply-grid{grid-template-columns:1fr}.atlas-heading h1{font-size:23px}.options button{padding:18px 14px;font-size:13px}.report h2 strong{font-size:34px}}@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}
